use super::*;
fn directory()->PathBuf{let p=std::env::temp_dir().join(format!("sdk-not-sent-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));fs::create_dir(&p).unwrap();p}
fn binding()->ImmutableBinding{ImmutableBinding{intent:"run:pkg".into(),key:"stable-fixture-key".into(),payload_hash:"a".repeat(64)}}
fn c(op:&str,now:u64)->Command{Command{op:op.into(),scope:"fixture-account".into(),now,request:"real-request".into(),write:true,binding:Some(Binding{intent:binding().intent,key:binding().key,payload_hash:binding().payload_hash}),authorized:true,lease_valid:true,permit_valid:true,..Default::default()}}
fn complete(s:&mut Store,now:u64,outcome:&str){let mut done=c("complete",now);done.outcome=outcome.into();s.command(done).unwrap();}
#[test]fn actual_core_rows_verify_without_mirroring_state_hash_or_field_order(){let p=directory();{let mut s=Store::open(&p,"fixture-account","sole-owner").unwrap();s.command(c("status",1)).unwrap();s.command(c("admit",10)).unwrap();complete(&mut s,20,"not_sent");let proof=verify_local_not_sent_v1(&p,"fixture-account",&binding(),"real-request",10).unwrap();assert_eq!(proof.evidence()["beforeRecord"]["state"]["active"]["network_started"],false);assert_eq!(proof.evidence()["completionRecord"]["state"]["active"],Value::Null);assert_eq!(proof.evidence()["binding"],serde_json::to_value(binding()).unwrap());let raw=proof.evidence()["beforeStateJson"].as_str().unwrap();assert!(raw.starts_with("{\"schema_version\":1,\"scope\":\"fixture-account\",\"last_clock\":"));assert!(verify_local_not_sent_v1(&p,"fixture-account",&binding(),"wrong-request",10).is_err());assert!(verify_local_not_sent_v1(&p,"fixture-account",&binding(),"real-request",11).is_err());}fs::remove_dir_all(p).unwrap();}
#[test]fn actual_checkpoint_generation_supported_but_erased_witness_never_inferred(){let p=directory();{let mut s=Store::open(&p,"fixture-account","sole-owner").unwrap();s.command(c("status",1)).unwrap();s.command(c("compact",2)).unwrap();s.command(c("admit",10)).unwrap();complete(&mut s,20,"not_sent");let proof=verify_local_not_sent_v1(&p,"fixture-account",&binding(),"real-request",10).unwrap();assert!(proof.evidence()["checkpointHash"].is_string());s.command(c("compact",30)).unwrap();s.command(c("status",31)).unwrap();assert!(verify_local_not_sent_v1(&p,"fixture-account",&binding(),"real-request",10).is_err());}fs::remove_dir_all(p).unwrap();}
#[test]fn network_fenced_success_rejection_and_crash_recovery_are_not_local_no_send(){for outcome in ["success","rejected","unknown"]{let p=directory();{let mut s=Store::open(&p,"fixture-account","sole-owner").unwrap();s.command(c("admit",10)).unwrap();s.command(c("network",11)).unwrap();complete(&mut s,20,outcome);assert!(verify_local_not_sent_v1(&p,"fixture-account",&binding(),"real-request",10).is_err());}fs::remove_dir_all(p).unwrap();}
 let p=directory();{let mut s=Store::open(&p,"fixture-account","first").unwrap();s.command(c("admit",10)).unwrap();}{let _s=Store::open(&p,"fixture-account","restart").unwrap();assert!(verify_local_not_sent_v1(&p,"fixture-account",&binding(),"real-request",10).is_err());}fs::remove_dir_all(p).unwrap();}
#[test]fn before_admit_absence_is_not_positive_proof_and_global_pending_blocks(){let p=directory();{let mut s=Store::open(&p,"fixture-account","owner").unwrap();s.command(c("status",1)).unwrap();assert!(verify_local_not_sent_v1(&p,"fixture-account",&binding(),"real-request",0).is_err());s.command(c("admit",10)).unwrap();complete(&mut s,20,"not_sent");let mut read=c("admit",3000);read.write=false;read.binding=None;read.request="another-read".into();s.command(read).unwrap();assert!(verify_local_not_sent_v1(&p,"fixture-account",&binding(),"real-request",10).is_err());}fs::remove_dir_all(p).unwrap();}
#[test]fn malformed_torn_blank_mutation_and_foreign_scope_refuse(){for damage in ["torn","blank","mutated"]{let p=directory();{let mut s=Store::open(&p,"fixture-account","owner").unwrap();s.command(c("admit",10)).unwrap();complete(&mut s,20,"not_sent");}let path=p.join("account-queue.jsonl");let original=fs::read_to_string(&path).unwrap();let changed=match damage{"torn"=>original.trim_end().to_owned(),"blank"=>format!("\n{original}"),_=>original.replace("real-request","fake-request")};fs::write(&path,changed).unwrap();assert!(verify_local_not_sent_v1(&p,"fixture-account",&binding(),"real-request",10).is_err());fs::remove_dir_all(p).unwrap();}
 let p=directory();{let mut s=Store::open(&p,"fixture-account","owner").unwrap();s.command(c("admit",10)).unwrap();complete(&mut s,20,"not_sent");assert!(verify_local_not_sent_v1(&p,"foreign",&binding(),"real-request",10).is_err());let mut wrong=binding();wrong.payload_hash="b".repeat(64);assert!(verify_local_not_sent_v1(&p,"fixture-account",&wrong,"real-request",10).is_err());}fs::remove_dir_all(p).unwrap();}
#[cfg(unix)]#[test]fn source_pin_rejects_identical_replacement_and_symlink(){use std::os::unix::fs::symlink;let p=directory();let path=p.join("source");fs::write(&path,b"bytes").unwrap();let mut pin=NotSentPinnedFile::read(&path,100).unwrap();fs::rename(&path,p.join("old-source")).unwrap();fs::write(&path,b"bytes").unwrap();assert!(pin.unchanged().is_err());fs::remove_file(&path).unwrap();symlink(p.join("old-source"),&path).unwrap();assert!(NotSentPinnedFile::read(&path,100).is_err());fs::remove_dir_all(p).unwrap();}
#[test]fn manifest_escape_or_version_switch_cannot_fall_back_to_legacy(){let p=directory();fs::write(p.join("account-queue-generation.guard"),b"fixture-account").unwrap();for version in [1,2]{fs::write(p.join("account-queue-manifest.json"),serde_json::to_vec(&json!({"schema_version":version,"scope":"fixture-account","journal":"../foreign","checkpoint":"checkpoint.json","checkpoint_hash":"a".repeat(64)})).unwrap()).unwrap();assert!(verify_local_not_sent_v1(&p,"fixture-account",&binding(),"real-request",10).is_err());}fs::remove_dir_all(p).unwrap();}
#[test]fn retained_original_prefix_uses_real_bytes_while_full_current_generation_is_verified(){let p=directory();{let mut s=Store::open(&p,"fixture-account","owner").unwrap();s.command(c("status",1)).unwrap();s.command(c("compact",2)).unwrap();s.command(c("admit",10)).unwrap();complete(&mut s,20,"not_sent");let original=verify_local_not_sent_v1(&p,"fixture-account",&binding(),"real-request",10).unwrap();let manifest:Manifest=serde_json::from_slice(&fs::read(p.join("account-queue-manifest.json")).unwrap()).unwrap();let prefix=fs::read(p.join(&manifest.journal)).unwrap();s.command(c("status",30)).unwrap();let retained=verify_retained_local_not_sent_v1(&p,"fixture-account",&binding(),"real-request",10).unwrap();assert_eq!(retained.evidence()["tailRecord"],original.evidence()["tailRecord"]);assert_eq!(retained.evidence()["tailStateJson"],original.evidence()["tailStateJson"]);assert_eq!(retained.evidence()["journalBytes"],prefix.len());assert_eq!(retained.evidence()["journalSha256"],format!("{:x}",Sha256::digest(&prefix)));assert_eq!(retained.evidence()["manifestSha256"],original.evidence()["manifestSha256"]);assert!(retained.evidence()["currentTailRecord"]["sequence"].as_u64()>retained.evidence()["tailRecord"]["sequence"].as_u64());let mut bytes=fs::read(p.join(&manifest.journal)).unwrap();let last=bytes.len()-2;bytes[last]^=1;fs::write(p.join(&manifest.journal),bytes).unwrap();assert!(verify_retained_local_not_sent_v1(&p,"fixture-account",&binding(),"real-request",10).is_err());}fs::remove_dir_all(p).unwrap();}
